{"tool": "write", "path": "reports/export.py", "content": """"Reports CSV exporter."""

import csv
import io


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    columns = list(columns)
    seen = set()
    for name in columns:
        if not isinstance(name, str):
            raise ValueError("column names must be strings")
        if name in seen:
            raise ValueError("duplicate column name: %r" % name)
        seen.add(name)

    out = io.StringIO(newline="")
    writer = csv.writer(out, lineterminator="\r\n")
    writer.writerow(columns)
    if columns:
        for row in rows:
            record = []
            for name in columns:
                value = row.get(name, None)
                if value is None:
                    record.append("")
                elif isinstance(value, str):
                    record.append(value)
                else:
                    record.append(str(value))
            writer.writerow(record)
    return out.getvalue()
